  // Vault
  'vault.title': 'כספת',
  'vault.subtitle': 'מאגר סודות מאובטח ומקומי לגמרי — מוצפן בעזרת מחזיק המפתחות של מערכת ההפעלה.',
  'vault.explainer':
    'הכספת אינה קובץ ואין לה שום קשר ל־.env שלכם. זהו מאגר מוצפן של מפתח/ערך שקיים רק על המחשב הזה — רשומות משויכות למאגר (או נשמרות כגלובליות), אבל הן לעולם לא נכתבות לתוך המאגר ולא נשלחות בקומיט או בפוש. השתמשו בה כדי לשמור סודות בהישג יד: חשיפה, העתקת ערך, או ״העתקה כ־.env״ כדי להדביק סט שלם היכן שבאמת צריך אותו.',
  'vault.unavailable':
    'הצפנת מערכת ההפעלה אינה זמינה במחשב הזה, ולכן הכספת מושבתת. (בלינוקס נדרש לשם כך keychain / libsecret.)',
  'vault.unlocking': 'פותח את הנעילה…',
  'vault.unreadable':
    'GitHuttBr לא הצליח לקרוא את הכספת שלך — מחזיק המפתחות היה נעול, הגישה נדחתה, או שעותק אחר של GitHuttBr שמר אותה. היא לא שונתה, ואי אפשר להוסיף או להסיר דבר עד שניתן יהיה לקרוא אותה. בטל את נעילת מחזיק המפתחות ונסה שוב.',
  'vault.replaceStore': 'יצירת כספת חדשה',
  'vault.replaceStoreTitle': 'ליצור כספת חדשה?',
  'vault.keychainUnavailable':
    'לא ניתן לפתוח את הכספת כרגע: מחזיק המפתחות של המערכת אינו זמין — הוא כבוי, השאלה שלו נדחתה או שלא ענה. דבר מהכספת לא יוצא ולא יובא. הפעל את מחזיק המפתחות בהגדרות ← אבטחה, או בטל את נעילתו, ונסה שוב.',
