  'attrs.title': 'מאפייני קבצים',
  'attrs.intro':
    '.gitattributes הוא הדרך שבה מאגר מלמד את git על הקבצים של עצמו: אילו הם בינאריים, אילו צריכים להשתרשר במקום להתנגש, אילו נשארים מחוץ לארכיון, ואילו סופי שורה להשתמש. הוא נוסע יחד עם השכפול, ולכן תיקון שלו כאן מתקן אותו לכולם.',
