  'attrs.checkTitle': 'מה חל על נתיב מסוים?',
  'attrs.checkHint':
    'הכללים מגיעים מכמה קבצים וההתאמה האחרונה מנצחת, ולכן קריאה שלהם היא ניחוש. כאן שואלים את git עצמו.',
  'attrs.check': 'בדיקה',
  'attrs.checkNothing': 'לא הוגדר שום דבר עבור הנתיב הזה.',
  'attrs.driversTitle': 'מנהלי התקן להשוואה',
  'attrs.driversHint':
    'מנהל diff הופך קובץ בלתי־קריא לטקסט לפני ש-git משווה אותו, וכך למסמך Word או לגיליון יש היסטוריה שאפשר לקרוא. Word‏, Excel ו-JSON משתמשים בממיר שמגיע עם GitHuttBr; השאר מוצעים אם הם מותקנים, ואחרת מוצגים באפור.',
  'attrs.driverMissing': 'הממיר לא מותקן',
  'attrs.needsBinary': 'דורש את {binary} ב־PATH שלכם.',
  'attrs.bundledConverter': 'מגיע עם GitHuttBr — אין צורך להתקין דבר.',
  'attrs.driverEphemeral': "מצביע לתיקיית AppImage זמנית",
  'attrs.driverEphemeralHint': "גרסת AppImage של GitHuttBr הגדירה את הממיר הזה. התיקייה שלו תחת ‎/tmp נעלמת כשהאפליקציה נסגרת, וכל משתמש אחר במחשב הזה יכול לשים בנתיב הזה תוכנה שה־git diff הבא שלכם יריץ. הסירו אותו.",
  'attrs.driverStale': 'הממיר קודם לגרסה 4.39',
  'attrs.driverStaleHint': 'זה הממיר שגרסאות עד 4.38 כללו תחת השם הישן של האפליקציה. האפליקציה מפנה מנהלי התקנים כאלה לממיר הנוכחי שלה בעצמה; את זה לא ניתן היה להפנות: הנתיב של AppImage משתנה בכל הפעלה, או שלא ניתן היה לכתוב את התצורה. השוואות של הקבצים האלה נכשלות אלא אם ההתקנה הישנה עדיין במקומה. הסר אותו, ואז הוסף את מנהל ההתקן שוב מההצעות שלמטה.',
  'attrs.driverRemove': "הסרה",
  'attrs.bundledAppImage': "לא זמין ב־AppImage: הממיר של GitHuttBr קיים רק בזמן שהאפליקציה רצה. התקינו את חבילת ה־‎.deb כדי להשתמש בו.",
  'attrs.filtersTitle': 'מסנני clean/smudge',
  'attrs.filtersHint': 'מסנן משכתב את תוכן הקובץ בכניסה (clean, בעת ההוספה לאינדקס) וביציאה (smudge, בעת צ׳קאאוט) — כך עובדים git-lfs והסרת מפתחות. מסנן שגוי משחית את עץ העבודה בשקט, ולכן GitHuttBr מתעקש על הרצת ניסיון מול קבצים אמיתיים לפני שמירה של כל דבר.',
  'attrs.filterCleanPh': 'פקודת clean (stdin → stdout)',
  'attrs.filterSmudgePh': 'פקודת smudge (רשות)',
  'attrs.filterRequired': 'חובה (required) — הפעולה נכשלת במקום להעביר קבצים כמו שהם',
  'attrs.filterDryRun': 'הרצת ניסיון',
