  'attrs.filterRoundtripOk': 'הלוך ושוב תקין — smudge(clean(file)) משחזר את המקור',
  'attrs.filterRoundtripDifferent': 'ההלוך ושוב שונה — צ׳קאאוט לא היה משחזר את הבייטים המקוריים',
  'attrs.filterRoundtripSkipped': 'clean רץ — אין פקודת smudge, ולכן אין בדיקת הלוך ושוב',
  'attrs.filterDangerTitle': 'לשמור מסנן לא מאומת?',
  'attrs.filterDangerMessage': 'הרצת הניסיון לא הצליחה לאמת את "{name}": פקודה נכשלה, שום דבר לא תאם, או שההלוך ושוב לא משחזר את הבייטים המקוריים. אם הוא שגוי, כל צ׳קאאוט של קבצים תואמים עלול להשחית את עץ העבודה בשקט.',
