  'keychain.whatHappens': 'אם תמשיכו, מערכת ההפעלה שלכם תבקש עכשיו לאשר גישה לרשומה בשם ״GitHuttBr Safe Storage״ — זו ש־GitHuttBr יוצר לעצמו.',
