  'keychain.tokenNotMoved': 'נשמר רק עד שתסגור את GitHuttBr: הוא עדיין לא הגיע למחזיק המפתחות של המערכת.',
  'keychain.tokenWeakBackend': 'נשמר רק עד שתסגור את GitHuttBr: אין מחזיק מפתחות פעיל, והאחסון הבסיסי לא היה מגן עליו.',
  'keychain.tokenStoreUnreadable': 'נשמר רק עד שתסגור את GitHuttBr: לא ניתן היה לקרוא את הטוקנים השמורים שלך. בטל את נעילת מחזיק המפתחות ונסה שוב.',
  'keychain.storeUnreadable': 'GitHuttBr לא הצליח לקרוא את הטוקנים השמורים שלך — מחזיק המפתחות היה נעול או שהגישה נדחתה. הם לא שונו. בטל את נעילת מחזיק המפתחות ונסה שוב; טוקנים שתוסיף בינתיים יישמרו רק עד שתסגור את האפליקציה.',
  'keychain.weakBackend': 'אין מחזיק מפתחות פעיל (GNOME Keyring או KWallet), ולכן המערכת משתמשת באחסון בסיסי, שרק מסתיר את הנתונים בסיסמה קבועה במקום להגן עליהם. אסימונים ששמרת בעבר נשארים קריאים, אבל חדשים נשמרים רק עד שתסגור את האפליקציה; הכספת ממשיכה לשמור שם. התקן או בטל את נעילת מחזיק המפתחות, ואז הפעל מחדש את GitHuttBr.',
  'keychain.replaceStore': 'יצירת מאגר טוקנים חדש',
  'keychain.replaceStoreTitle': 'ליצור מאגר טוקנים חדש?',
  'keychain.replaceStoreMessage': 'GitHuttBr יפסיק לחכות לטוקנים השמורים שאינו יכול לקרוא, ויצור מאגר חדש שמכיל רק את הטוקנים שהוקלדו בהפעלה הזו. הקובץ הישן יישמר לצדו כגיבוי למשך 30 יום, ואז יימחק. עשה זאת רק אם הטוקנים האלה אבדו לתמיד — למשל, עותק אחר של GitHuttBr שמר אותם.',
