  'gitError.workflowScopeToken': 'GitHub דחה את הדחיפה: היא משנה את ה-workflow ‏{file}, ואסימון הגישה האישי לא יכול לערוך workflows. תנו לו את הרשאת `workflow` (אסימון קלאסי) או Workflows: Read and write (fine-grained) ודחפו שוב.',
